def seed_food_database():
    """向 food_database 写入种子数据（增量式，INSERT OR IGNORE 避免重复）"""
    from models import get_db
    db = get_db()
    added = 0
    for item in FOOD_SEED_DATA:
        try:
            result = db.execute(
                "INSERT OR IGNORE INTO food_database (name, calories_per_100g, protein_per_100g, fat_per_100g, carbs_per_100g, category) VALUES (?, ?, ?, ?, ?, ?)",
                (item['name'], item['calories_per_100g'], item['protein_per_100g'],
                 item['fat_per_100g'], item['carbs_per_100g'], item['category'])
            )
            if result.rowcount > 0:
                added += 1
        except Exception:
            pass
    db.commit()
    db.close()
    if added > 0:
        print(f'[food_seed] 新增 {added} 种食物')
